-- Sprint 60: provider-neutral transactional email infrastructure.
create table if not exists public.email_templates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,workspace_id uuid not null references public.workspaces(id)on delete cascade,template_key text not null,name text not null,locale text not null default'en',subject_template text not null,html_template text not null,text_template text not null,is_active boolean not null default true,version integer not null default 1,created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,template_key,locale));
create table if not exists public.email_messages(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,workspace_id uuid not null references public.workspaces(id)on delete cascade,purpose text not null,recipients jsonb not null check(jsonb_typeof(recipients)='array'and jsonb_array_length(recipients)between 1 and 50),locale text not null default'en',variables_ciphertext text not null,subject text not null,provider text not null check(provider in('resend','sendgrid','postmark','smtp')),status text not null default'queued'check(status in('queued','processing','delivered','failed','bounced','cancelled')),attempts integer not null default 0,max_attempts integer not null default 5,scheduled_at timestamptz not null default now(),started_at timestamptz,delivered_at timestamptz,latency_ms integer,provider_message_id text,last_error text,dedupe_key text not null,source_type text,source_id uuid,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,dedupe_key));
create table if not exists public.email_delivery_attempts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,workspace_id uuid not null references public.workspaces(id)on delete cascade,message_id uuid not null references public.email_messages(id)on delete cascade,provider text not null,status text not null check(status in('processing','delivered','failed','bounced')),latency_ms integer,error_code text,started_at timestamptz not null default now(),completed_at timestamptz);
create index if not exists email_queue_due_idx on public.email_messages(provider,status,scheduled_at)where status='queued';create index if not exists email_history_idx on public.email_messages(workspace_id,created_at desc);create index if not exists email_attempt_message_idx on public.email_delivery_attempts(message_id,started_at desc);
alter table public.email_templates enable row level security;alter table public.email_messages enable row level security;alter table public.email_delivery_attempts enable row level security;
create policy email_templates_member_read on public.email_templates for select to authenticated using(public.is_organization_member(organization_id));create policy email_messages_member_read on public.email_messages for select to authenticated using(public.is_organization_member(organization_id));create policy email_attempts_member_read on public.email_delivery_attempts for select to authenticated using(public.is_organization_member(organization_id));
insert into public.permissions(key,name,scope)values('email.read','Read email infrastructure','workspace'),('email.manage','Manage email infrastructure','workspace')on conflict(key)do update set name=excluded.name,scope=excluded.scope;
insert into public.role_permissions(role_id,permission_id)select r.id,p.id from public.roles r cross join public.permissions p where p.key='email.read'and r.code in('organization_owner','organization_admin','manager','operations','finance','support','read_only')or p.key='email.manage'and r.code in('organization_owner','organization_admin','operations')on conflict do nothing;
create or replace function public.can_manage_email_platform(p_workspace_id uuid)returns boolean language sql stable security definer set search_path=public as $$select coalesce(public.current_workspace_role(p_workspace_id)in('organization_owner','organization_admin','operations'),false)$$;
create or replace function public.enqueue_email_message(p_workspace_id uuid,p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare v_org uuid;v_id uuid;begin select organization_id into v_org from workspaces where id=p_workspace_id;if v_org is null or(current_setting('role',true)<>'service_role'and not public.is_organization_member(v_org))then raise exception'email workspace access denied';end if;if p_input->>'provider'not in('resend','sendgrid','postmark','smtp')then raise exception'invalid email provider';end if;insert into email_messages(organization_id,workspace_id,purpose,recipients,locale,variables_ciphertext,subject,provider,scheduled_at,dedupe_key,source_type,source_id,created_by)values(v_org,p_workspace_id,p_input->>'purpose',p_input->'to',coalesce(p_input->>'locale','en'),p_input->>'variablesCiphertext',p_input->>'purpose',p_input->>'provider',coalesce((p_input->>'scheduledAt')::timestamptz,now()),p_input->>'dedupeKey',nullif(p_input->>'sourceType',''),nullif(p_input->>'sourceId','')::uuid,auth.uid())on conflict(organization_id,dedupe_key)do update set updated_at=email_messages.updated_at returning id into v_id;insert into activity_events(organization_id,workspace_id,event_type,title,actor_id,related_type,related_id,metadata)values(v_org,p_workspace_id,'email.queued','Transactional email queued',auth.uid(),'email',v_id,jsonb_build_object('purpose',p_input->>'purpose','provider',p_input->>'provider'));return v_id;end$$;
create or replace function public.claim_email_message(p_provider text)returns jsonb language plpgsql security definer set search_path=public as $$declare r email_messages%rowtype;begin if current_setting('role',true)<>'service_role'then raise exception'service role required';end if;select*into r from email_messages where provider=p_provider and status='queued'and scheduled_at<=now()and attempts<max_attempts order by scheduled_at for update skip locked limit 1;if r.id is null then return null;end if;update email_messages set status='processing',started_at=now(),attempts=attempts+1,updated_at=now()where id=r.id;insert into email_delivery_attempts(organization_id,workspace_id,message_id,provider,status)values(r.organization_id,r.workspace_id,r.id,r.provider,'processing');return to_jsonb(r);end$$;
create or replace function public.complete_email_message(p_message_id uuid,p_success boolean,p_provider_message_id text,p_latency_ms integer,p_error text)returns void language plpgsql security definer set search_path=public as $$declare r email_messages%rowtype;v_status text;begin if current_setting('role',true)<>'service_role'then raise exception'service role required';end if;select*into r from email_messages where id=p_message_id for update;if r.id is null then raise exception'email message not found';end if;v_status:=case when p_success then'delivered'when r.attempts>=r.max_attempts then'failed'else'queued'end;update email_messages set status=v_status,provider_message_id=case when p_success then p_provider_message_id else provider_message_id end,latency_ms=p_latency_ms,last_error=case when p_success then null else left(p_error,500)end,delivered_at=case when p_success then now()else delivered_at end,scheduled_at=case when not p_success and r.attempts<r.max_attempts then now()+(interval'1 minute'*power(2,r.attempts))else scheduled_at end,updated_at=now()where id=p_message_id;update email_delivery_attempts set status=case when p_success then'delivered'else'failed'end,latency_ms=p_latency_ms,error_code=case when p_success then null else left(p_error,120)end,completed_at=now()where message_id=p_message_id and status='processing';insert into activity_events(organization_id,workspace_id,event_type,title,related_type,related_id,metadata)values(r.organization_id,r.workspace_id,case when p_success then'email.delivered'else'email.delivery_failed'end,case when p_success then'Transactional email delivered'else'Transactional email delivery failed'end,'email',r.id,jsonb_build_object('provider',r.provider,'latency_ms',p_latency_ms,'attempt',r.attempts));end$$;
create or replace function public.retry_email_message(p_workspace_id uuid,p_message_id uuid)returns void language plpgsql security definer set search_path=public as $$declare v_org uuid;begin if not can_manage_email_platform(p_workspace_id)then raise exception'insufficient email permission';end if;update email_messages set status='queued',scheduled_at=now(),last_error=null,updated_at=now()where id=p_message_id and workspace_id=p_workspace_id and status in('failed','bounced');if not found then raise exception'failed email not found';end if;select organization_id into v_org from workspaces where id=p_workspace_id;insert into organization_audit_events(organization_id,workspace_id,actor_id,event_type,subject_id)values(v_org,p_workspace_id,auth.uid(),'email.retry_requested',p_message_id);end$$;
create or replace function public.save_email_template(p_workspace_id uuid,p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare v_org uuid;v_id uuid;begin if not can_manage_email_platform(p_workspace_id)then raise exception'insufficient email permission';end if;select organization_id into v_org from workspaces where id=p_workspace_id;insert into email_templates(organization_id,workspace_id,template_key,name,locale,subject_template,html_template,text_template,is_active,created_by,updated_by)values(v_org,p_workspace_id,p_input->>'key',p_input->>'name',p_input->>'locale',p_input->>'subject',p_input->>'html',p_input->>'text',coalesce((p_input->>'active')::boolean,true),auth.uid(),auth.uid())on conflict(workspace_id,template_key,locale)do update set name=excluded.name,subject_template=excluded.subject_template,html_template=excluded.html_template,text_template=excluded.text_template,is_active=excluded.is_active,updated_by=auth.uid(),updated_at=now(),version=email_templates.version+1 returning id into v_id;insert into organization_audit_events(organization_id,workspace_id,actor_id,event_type,subject_id,metadata)values(v_org,p_workspace_id,auth.uid(),'email.template_saved',v_id,jsonb_build_object('key',p_input->>'key','locale',p_input->>'locale'));return v_id;end$$;
create or replace function public.email_delivery_statistics(p_workspace_id uuid)returns table(queued bigint,delivered bigint,failed bigint,bounced bigint,retries bigint,average_latency_ms numeric)language sql stable security definer set search_path=public as $$select count(*)filter(where status in('queued','processing')),count(*)filter(where status='delivered'),count(*)filter(where status='failed'),count(*)filter(where status='bounced'),coalesce(sum(greatest(attempts-1,0)),0),round(avg(latency_ms)filter(where status='delivered'))from email_messages where workspace_id=p_workspace_id and public.is_organization_member(organization_id)$$;
revoke all on function public.enqueue_email_message(uuid,jsonb),public.claim_email_message(text),public.complete_email_message(uuid,boolean,text,integer,text),public.retry_email_message(uuid,uuid),public.save_email_template(uuid,jsonb),public.email_delivery_statistics(uuid),public.can_manage_email_platform(uuid)from public;grant execute on function public.enqueue_email_message(uuid,jsonb),public.retry_email_message(uuid,uuid),public.save_email_template(uuid,jsonb),public.email_delivery_statistics(uuid),public.can_manage_email_platform(uuid)to authenticated;grant execute on function public.enqueue_email_message(uuid,jsonb),public.claim_email_message(text),public.complete_email_message(uuid,boolean,text,integer,text)to service_role;grant select on public.email_templates,public.email_messages,public.email_delivery_attempts to authenticated;
